import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Einträge anlegen und bearbeiten","description":"Einträge in einem Grid erfassen, ändern und teilen.","frontmatter":{"title":"Einträge anlegen und bearbeiten","description":"Einträge in einem Grid erfassen, ändern und teilen."},"headers":[],"relativePath":"grids/eintraege.md","filePath":"grids/eintraege.md","lastUpdated":1786174778000}'),a={name:"grids/eintraege.md"};function d(s,e,l,o,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="eintrage-anlegen-und-bearbeiten" tabindex="-1">Einträge anlegen und bearbeiten <a class="header-anchor" href="#eintrage-anlegen-und-bearbeiten" aria-label="Permalink to &quot;Einträge anlegen und bearbeiten&quot;">​</a></h1><p>Ein <strong>Eintrag</strong> ist eine Zeile in einem Grid.</p><h2 id="anlegen" tabindex="-1">Anlegen <a class="header-anchor" href="#anlegen" aria-label="Permalink to &quot;Anlegen&quot;">​</a></h2><p>Vier Wege führen zu einem neuen Eintrag:</p><table tabindex="0"><thead><tr><th>Weg</th><th>Wann sinnvoll</th></tr></thead><tbody><tr><td>Direkt in der Tabelle</td><td>Beim Aufbau, für schnelle Ergänzungen</td></tr><tr><td>Über <strong>Neuen Eintrag erstellen</strong></td><td>Wenn viele Felder zu füllen sind</td></tr><tr><td>Über ein <a href="/formulare/formular-erstellen">Formular</a></td><td>Wenn andere Personen Daten liefern</td></tr><tr><td>Über einen <a href="/flows/aktionen">Flow</a></td><td>Wenn Einträge automatisch entstehen</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Neue Einträge lösen Flows aus</p><p>Hängt ein Flow mit dem Auslöser <em>Neuer Eintrag</em> an diesem Grid, startet er bei <strong>jedem</strong> neuen Eintrag — unabhängig davon, auf welchem Weg er entstanden ist.</p><p>Das gilt auch beim <a href="/grids/csv-import">CSV-Import</a>: 500 importierte Zeilen bedeuten 500 Flow-Durchläufe.</p></div><h2 id="bearbeiten" tabindex="-1">Bearbeiten <a class="header-anchor" href="#bearbeiten" aria-label="Permalink to &quot;Bearbeiten&quot;">​</a></h2><h3 id="in-der-tabelle" tabindex="-1">In der Tabelle <a class="header-anchor" href="#in-der-tabelle" aria-label="Permalink to &quot;In der Tabelle&quot;">​</a></h3><p>Ein Klick in eine Zelle macht sie bearbeitbar. Änderungen werden sofort gespeichert — es gibt keinen Speichern-Knopf.</p><div class="tip custom-block"><p class="custom-block-title">Kein Rückgängig in der Tabelle</p><p>Eine überschriebene Zelle lässt sich nicht mit einem Tastenkürzel zurückholen. Der <a href="/grids/versionsverlauf">Versionsverlauf</a> zeigt aber den früheren Wert und erlaubt, ihn wiederherzustellen.</p></div><h3 id="in-der-detailansicht" tabindex="-1">In der Detailansicht <a class="header-anchor" href="#in-der-detailansicht" aria-label="Permalink to &quot;In der Detailansicht&quot;">​</a></h3><p>Ein Klick auf die Zeile öffnet den Eintrag mit allen Feldern untereinander — auch denen, die in der aktuellen Ansicht ausgeblendet sind.</p><p>Der Dialog heißt <strong>Eintrag bearbeiten</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Ausgeblendete Felder sind nicht weg</p><p>Ein häufiges Missverständnis: Was in der Ansicht ausgeblendet ist, existiert weiterhin und ist in der Detailansicht sichtbar und bearbeitbar. → <a href="/ansichten/spalten-verwalten">Spalten verwalten</a></p></div><h2 id="emoticon-kurzbefehle" tabindex="-1">Emoticon-Kurzbefehle <a class="header-anchor" href="#emoticon-kurzbefehle" aria-label="Permalink to &quot;Emoticon-Kurzbefehle&quot;">​</a></h2><p>In Textfeldern werden einige Zeichenfolgen beim Tippen automatisch durch ein Symbol ersetzt:</p><table tabindex="0"><thead><tr><th>Eingabe</th><th>Wird zu</th></tr></thead><tbody><tr><td><code>(/)</code></td><td>✅</td></tr><tr><td><code>(x)</code> oder <code>(×)</code></td><td>❌</td></tr><tr><td><code>(!)</code></td><td>❗</td></tr><tr><td><code>(?)</code></td><td>❓</td></tr><tr><td><code>(Y)</code> oder <code>(y)</code></td><td>👍</td></tr><tr><td><code>(N)</code> oder <code>(n)</code></td><td>👎</td></tr></tbody></table><p>Die Ersetzung greift nur, wenn der Kurzbefehl <strong>am Anfang oder nach einem Leerzeichen</strong> steht und ein Leerzeichen, ein Zeilenumbruch oder das Feldende folgt. Text wie <code>Version(x)</code> bleibt also unverändert.</p><div class="tip custom-block"><p class="custom-block-title">Nützlich für Statusspalten</p><p>Für kurze Vermerke — erledigt, offen, Rückfrage — sind die Symbole auf einen Blick erfassbar und brauchen keine eigene Auswahlspalte.</p><p>Für auswertbare Zustände ist ein Feld vom Typ <strong>Einzelauswahl</strong> oder <strong>Häkchen</strong> trotzdem besser: Danach lässt sich filtern und gruppieren, nach einem Symbol im Freitext nicht sinnvoll.</p></div><h2 id="gesperrte-und-schreibgeschutzte-felder" tabindex="-1">Gesperrte und schreibgeschützte Felder <a class="header-anchor" href="#gesperrte-und-schreibgeschutzte-felder" aria-label="Permalink to &quot;Gesperrte und schreibgeschützte Felder&quot;">​</a></h2><p>Manche Felder lassen sich nicht bearbeiten:</p><table tabindex="0"><thead><tr><th>Grund</th><th>Erkennbar an</th></tr></thead><tbody><tr><td><strong>Berechneter Typ</strong> — Wert übernehmen, Summe berechnen, Formel</td><td>Grundsätzlich schreibgeschützt</td></tr><tr><td><strong>Automatisches Feld</strong> — Erstellt am, Erstellt von</td><td>Grundsätzlich schreibgeschützt</td></tr><tr><td><strong>In dieser Ansicht gesperrt</strong></td><td>Hinweis <em>Spalte ist in dieser Ansicht gesperrt</em></td></tr><tr><td><strong>Fehlende Berechtigung</strong></td><td>Kein Bearbeitungsmodus, keine Meldung</td></tr></tbody></table><h2 id="wenn-ein-eintrag-verschwindet" tabindex="-1">Wenn ein Eintrag verschwindet <a class="header-anchor" href="#wenn-ein-eintrag-verschwindet" aria-label="Permalink to &quot;Wenn ein Eintrag verschwindet&quot;">​</a></h2><p>Bearbeiten Sie einen Eintrag so, dass er nicht mehr zum Filter der Ansicht passt, meldet ApptiveGrid <strong>Zeile gefiltert</strong> und blendet ihn aus.</p><div class="tip custom-block"><p class="custom-block-title">Der Eintrag ist nicht weg</p><p>Er erfüllt nur die Filterbedingung nicht mehr. In einer ungefilterten Ansicht ist er vorhanden. Das passiert typischerweise, wenn man in einer Ansicht „Offene Aufgaben&quot; den Status auf <code>Erledigt</code> setzt.</p></div><h2 id="gleichzeitiges-arbeiten" tabindex="-1">Gleichzeitiges Arbeiten <a class="header-anchor" href="#gleichzeitiges-arbeiten" aria-label="Permalink to &quot;Gleichzeitiges Arbeiten&quot;">​</a></h2><p>Ändert jemand anderes das Grid, meldet ApptiveGrid <strong>Dieses Grid wurde aktualisiert</strong>. Laden Sie die Ansicht neu, um den aktuellen Stand zu sehen.</p><h2 id="einen-eintrag-teilen" tabindex="-1">Einen Eintrag teilen <a class="header-anchor" href="#einen-eintrag-teilen" aria-label="Permalink to &quot;Einen Eintrag teilen&quot;">​</a></h2><p>Über das Zeilenmenü <strong>Eintrag teilen</strong> erzeugen Sie einen Link, über den eine Person <strong>genau diesen</strong> Eintrag bearbeiten kann.</p><blockquote><p><strong>Formular zum bearbeiten teilen</strong><em>Teile ein Formular zum bearbeiten des Eintrags mit Anderen.</em></p></blockquote><p>Voraussetzung ist ein Formular auf diesem Grid. Fehlt es: <em>Erstellen Sie erst ein Formular um den Eintrag mit anderen zu teilen.</em></p><div class="tip custom-block"><p class="custom-block-title">Rückmeldungen einholen ohne Zugriff zu geben</p><p>So lassen Sie Externe einen einzelnen Datensatz ergänzen oder korrigieren, ohne sie in den <a href="/zusammenarbeit/personen-einladen">Space einzuladen</a> — und ohne dass sie andere Einträge sehen.</p></div><p>→ <a href="/formulare/eintraege-bearbeiten">Einträge per Formular bearbeiten</a></p><h2 id="einen-eintrag-drucken" tabindex="-1">Einen Eintrag drucken <a class="header-anchor" href="#einen-eintrag-drucken" aria-label="Permalink to &quot;Einen Eintrag drucken&quot;">​</a></h2><p>Über die Detailansicht lässt sich ein Eintrag in einer Druckansicht öffnen.</p><h2 id="grenzen" tabindex="-1">Grenzen <a class="header-anchor" href="#grenzen" aria-label="Permalink to &quot;Grenzen&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Anzahl der Einträge je Grid ist tarifabhängig</p><p>Nähern Sie sich der Grenze, blendet ApptiveGrid einen Hinweis ein.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/grids/suche">Suche</a> — Einträge wiederfinden</li><li><a href="/grids/eintraege-loeschen">Einträge löschen</a></li><li><a href="/grids/versionsverlauf">Versionsverlauf</a></li><li><a href="/grids/felder">Felder anlegen und ändern</a></li></ul>',39)])])}const b=n(a,[["render",d]]);export{g as __pageData,b as default};
